  deg[(r,c)]=sum(0<=r+dr<H and 0<=c+dc<W and A[r+dr,c+dc]==target for dr,dc in offs[:4])
 D={col:{} for col in source_colors}
 for col in source_colors:
  q=deque()
  for p in deg:
   r,c=p
   ks={comps[nr,nc] for dr,dc in offs[:4] if 0<=(nr:=r+dr)<H and 0<=(nc:=c+dc)<W and comps[nr,nc]>0}
   if any(cc[k]==col for k in ks): D[col][p]=0;q.append(p)
  while q:
