    nr,nc=r+dr,c+dc; p=(nr,nc)
    if p in deg and p not in D[col] and deg[p]<=maxdeg and (deg[(r,c)]<=maxdeg or D[col][(r,c)]==0):
     D[col][p]=D[col][(r,c)]+1;q.append(p)
 O=A.copy()
